mapper.select:
SELECT game_id AS "gameId", step_id AS "stepId", shield_ref AS "shieldRef", amount_formula_key AS "amountFormulaKey", duration_formula_key AS "durationFormulaKey", value_policy_type_id AS "valuePolicyTypeId", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.shield_effect_details WHERE game_id = #{gameId}
AND step_id = #{stepId}
ORDER BY step_id

mapper.delete:
DELETE FROM public.shield_effect_details
WHERE game_id = #{gameId}
  AND step_id = #{stepId}
